def _validate_url(url: str) -> None:
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise HTTPException(
            status_code=400, detail="Invalid scheme: only http and https are allowed"
        )
    if not parsed.netloc:
        raise HTTPException(status_code=400, detail="Invalid URL: missing hostname")

    # Resolve hostname to IP(s) and ensure they are global
    try:
        infos = socket.getaddrinfo(parsed.hostname, None)
    except socket.gaierror:
        raise HTTPException(
            status_code=400, detail="Invalid destination: hostname could not be resolved"
        )

