        ip = info[4][0]
        try:
            ip_obj = ipaddress.ip_address(ip)
        except ValueError:
            continue
        if not ip_obj.is_global or ip_obj.is_private or ip_obj.is_loopback:
            raise HTTPException(
                status_code=400,
                detail="Invalid destination: private or restricted IP address",
            )


